(() => {
'use strict';
const $=id=>document.getElementById(id),root=$('account-content'),msg=$('account-message'),shell=window.AcademyShell;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try{const course=new URLSearchParams(location.search).get('course');if(/^[a-z][a-z0-9-]{1,30}$/.test(course||''))sessionStorage.setItem('dba-course-intent',course)}catch{}
const modes=['sign-in','register','forgot-password','reset-password','auth/confirm','onboarding','account'];
const supplied=location.pathname==='/auth.html'?new URLSearchParams(location.search).get('mode'):location.pathname.slice(1),mode=modes.includes(supplied)?supplied:'sign-in';
let ready=false,session={signedIn:false,registered:false},config={};
$('account-tabs').innerHTML=`<a href="/sign-in" class="${mode==='sign-in'?'active':''}" ${mode==='sign-in'?'aria-current="page"':''}>Sign in</a><a href="/register" class="${mode==='register'?'active':''}" ${mode==='register'?'aria-current="page"':''}>Register</a>`;
function message(text,type='success'){msg.textContent=text;msg.className='auth-message '+type;msg.setAttribute('role',type==='error'?'alert':'status');if(type==='error')msg.focus({preventScroll:true})}
async function api(path,method='GET',body){const r=await fetch('/api/'+path,{method,headers:{'content-type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});let b;try{b=await r.json()}catch{throw Error('The account service is unavailable. Please try again.')}if(!r.ok)throw Object.assign(Error(b.error||'The account action could not be completed.'),{status:r.status});return b}
function title(value){$('account-page-label').textContent=value;document.title=value+' — DigitalBurj Academy'}
function input(name,label,{type='text',extra='',help='',required=true}={}){return `<label class="field" for="account-${name}"><span>${label}</span>${type==='password'?'<span class="password-field">':''}<input id="account-${name}" name="${name}" type="${type}" ${required?'required':''} ${extra} ${help?`aria-describedby="help-${name}"`:''}>${type==='password'?`<button class="password-toggle" type="button" data-password="account-${name}" aria-label="Show ${label.toLowerCase()}" aria-pressed="false">Show</button></span>`:''}${help?`<small class="field-help" id="help-${name}">${help}</small>`:''}</label>`}
const email=()=>input('email','Email address',{type:'email',extra:'autocomplete="email" maxlength="254" autocapitalize="none" spellcheck="false"'});
const newPassword=()=>input('password','Password',{type:'password',extra:'minlength="12" maxlength="128" autocomplete="new-password"',help:'Use 12–128 characters. A unique passphrase is easier to remember.'})+input('confirmPassword','Confirm password',{type:'password',extra:'minlength="12" maxlength="128" autocomplete="new-password"'});
function form(heading,intro,fields,button){title(heading);root.innerHTML=`<h1>${heading}</h1><p class="form-intro">${intro}</p><form id="account-form">${fields}<button class="btn primary auth-submit" type="submit" ${ready?'':'disabled'}>${button}</button></form>`;const confirm=$('account-confirmPassword');if(confirm){const validate=()=>confirm.setCustomValidity(confirm.value&&confirm.value!==$('account-password').value?'Your passwords do not match. Enter the same password in both fields.':'');confirm.addEventListener('input',validate);$('account-password').addEventListener('input',validate)}}
function navigate(next){location.assign(['/dashboard','/onboarding','/register','/reset-password'].includes(next)?next:'/dashboard')}
async function submit(e,run){e.preventDefault();if(!ready){message('Secure account access is temporarily unavailable. Please retry.','error');return}const button=e.target.querySelector('[type=submit]');if(button.disabled)return;button.disabled=true;button.setAttribute('aria-busy','true');const label=button.textContent;button.textContent='Please wait…';message('Checking your request…','pending');try{await run(new FormData(e.target))}catch(error){message(error.message,'error')}finally{button.disabled=!ready;button.removeAttribute('aria-busy');button.textContent=label}}
function accountHelp(){return '<details class="auth-inline-help"><summary>How account access works</summary><p>Sign in using the available identity method, complete your learner profile and agree to store your learning records. Then your dashboard opens with the free foundation courses. A confirmed course purchase gives access to that course only. Staff permissions are appointed separately.</p></details>'}
function nativeButton(){const target=mode==='register'?'/register':'/dashboard';return `<a class="btn primary auth-sso" data-chatgpt-signin data-tool-label="chatgpt" href="/signin-with-chatgpt?return_to=${encodeURIComponent(target)}" target="_top">${window.ToolIcons.icon('chatgpt',20)}${mode==='register'?'Register with ChatGPT':'Continue with ChatGPT'}</a>`}
function nativeEntry(){const heading=mode==='register'?'Create your learner account':'Welcome back.';title(heading);root.innerHTML=`<h1>${heading}</h1><p class="form-intro">${mode==='register'?'Use your ChatGPT account to identify yourself securely. Complete your Academy profile in the next step.':'Sign in securely to open your registered Academy account.'}</p>${nativeButton()}<p class="small muted" style="margin-top:18px">Your password stays with ChatGPT. DigitalBurj does not receive it. No course or tool opens until your Academy registration is complete.</p><div class="auth-form-links">${mode==='register'?'<span>Already registered? <a href="/sign-in">Sign in</a></span>':'<span>New learner? <a href="/register">Create your account</a></span>'}</div>${accountHelp()}`}
function standardForm(){if(mode==='register')form('Create your learner account','Confirm your email and complete your profile before entering the Academy.',email()+newPassword()+'<label class="checkbox"><input type="checkbox" name="consent" required><span>I agree to create my Academy account and store my profile and learning records.</span></label>','Create account');else if(mode==='forgot-password')form('Reset your password','Enter your account email to request recovery instructions.',email(),'Send recovery email');else form('Welcome back.','Sign in to continue your Academy learning.',email()+input('password','Password',{type:'password',extra:'maxlength="128" autocomplete="current-password"'}),'Sign in');
 root.insertAdjacentHTML('beforeend',`<div class="auth-form-links">${mode==='register'?'<span>Already registered? <a href="/sign-in">Sign in</a></span>':mode==='forgot-password'?'<a href="/sign-in">Back to sign in</a>':'<a href="/forgot-password">Forgot password?</a>'}</div>${accountHelp()}`);
 $('account-form').onsubmit=e=>submit(e,async data=>{const result=await api(mode==='register'?'auth/signup':mode==='forgot-password'?'auth/recover':'auth/login','POST',{email:String(data.get('email')).trim(),password:data.get('password'),consent:!!data.get('consent')});if(result.next)navigate(result.next);else{message(result.message||'Check your email for the next step.');$('account-form').reset()}});
}
root.addEventListener('click',async e=>{const native=e.target.closest('[data-chatgpt-signin]');if(native){e.preventDefault();native.setAttribute('aria-busy','true');try{await api('auth/logout','POST',{});window.top.location.assign(native.href)}catch(error){message(error.message,'error');native.removeAttribute('aria-busy')}return}const b=e.target.closest('[data-password]');if(!b)return;const field=$(b.dataset.password),show=field.type==='password';field.type=show?'text':'password';b.textContent=show?'Hide':'Show';b.setAttribute('aria-pressed',String(show));b.setAttribute('aria-label',(show?'Hide ':'Show ')+(field.name==='confirmPassword'?'confirm password':field.name==='currentPassword'?'current password':'password'))});
async function signout(button){button.disabled=true;try{const result=await api('auth/logout','POST',{});try{localStorage.setItem('dba-auth-logout',String(Date.now()))}catch{}location.assign(result.next==='/signout-with-chatgpt?return_to=%2Fsign-in'?result.next:'/sign-in')}catch(error){message(error.message,'error');button.disabled=false}}
async function profile(){if(!session.signedIn){location.replace('/sign-in');return}const p=(await api('account/profile')).profile,creating=!session.registered;const programmes=[{id:'DB-00',title:'Digital confidence — recommended'},{id:'DB-07',title:'Digital safety & responsible work'}];if(p?.goal&&!programmes.some(x=>x.id===p.goal))programmes.push({id:p.goal,title:'Your current starting programme'});
 form(creating?'Complete your registration':'Your learning profile',creating?'One final step. Set your name and learning pace to open your Academy dashboard.':'Keep your name and learning pace up to date.',input('name','Full name',{extra:'autocomplete="name" minlength="2" maxlength="120"'})+input('country','Country (optional)',{required:false,extra:'autocomplete="country-name" maxlength="100"'})+`<label class="field" for="account-goal"><span>Start with a free course</span><select id="account-goal" name="goal">${programmes.map(p=>`<option value="${esc(p.id)}">${esc(p.title)}</option>`).join('')}</select></label>`+input('hours','Hours available each week',{type:'number',extra:'min="1" max="40" step="1" value="5"'})+'<label class="checkbox"><input type="checkbox" name="consent" required><span>I agree to store my learner profile and learning records in this Academy.</span></label>',creating?'Create my account & enter Academy':'Save profile & continue');if(p)for(const k of ['name','country','goal','hours'])root.querySelector(`[name="${k}"]`).value=p[k];
 root.insertAdjacentHTML('beforeend',`<p class="profile-email">Securely signed in as ${esc(session.user.email)}</p><div class="auth-form-links">${session.registered?'<a href="/dashboard">Return to my courses</a>':''}${session.user.provider!=='chatgpt'?'<a href="/reset-password">Change password</a>':''}</div><button class="btn small" id="logout" type="button" style="margin-top:18px">Sign out</button>${accountHelp()}`);$('logout').onclick=e=>signout(e.target);$('account-form').onsubmit=e=>submit(e,async data=>{await api('account/profile','PUT',{name:data.get('name'),country:data.get('country'),goal:data.get('goal'),hours:Number(data.get('hours')),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,consent:!!data.get('consent')});navigate('/dashboard')});
}
async function boot(){const query=new URLSearchParams(location.search),isConfirm=mode==='auth/confirm'||(mode==='reset-password'&&query.has('token_hash')),tokenHash=query.get('token_hash'),type=query.get('type');if(isConfirm)history.replaceState({},'',location.pathname);
 const results=await Promise.allSettled([api('auth/config'),api('auth/session')]);config=results[0].status==='fulfilled'?results[0].value:{};session=results[1].status==='fulfilled'?results[1].value:{signedIn:false,registered:false};ready=!!(config.configured&&config.secureSessions);
 if(!ready){title('Secure account access');root.innerHTML='<h1>Account access is temporarily unavailable.</h1><p>The Academy remains locked. Please retry after the sign-in service is available.</p><button class="btn primary" type="button" id="retry-account">Try again</button>';$('retry-account').onclick=()=>location.reload();return}
 if(isConfirm){if(!tokenHash)throw Error('This link is incomplete. Request a fresh confirmation email.');root.innerHTML='<h1>Confirming your email…</h1><p>Please keep this page open.</p>';const result=await api('auth/confirm','POST',{tokenHash,type});navigate(result.next);return}
 if(mode==='account'||mode==='onboarding'||(mode==='register'&&session.signedIn&&!session.registered)){await profile();return}
 if(session.signedIn&&['sign-in','register'].includes(mode)){title(session.registered?'Welcome back.':'Complete your registration');root.innerHTML=`<h1>${session.registered?'Welcome back.':'Your secure sign-in is complete.'}</h1><p class="form-intro">${session.registered?'Your learner account is ready. Continue to your courses.':'Complete your learner profile before opening any Academy course or tool.'}</p><p class="profile-email">${esc(session.user.email)}</p><a class="btn primary auth-submit" href="${session.registered?'/dashboard':'/register'}">${session.registered?'Open my courses':'Complete registration'}</a><button class="btn small" id="logout" type="button" style="margin-top:18px">Sign out</button>${accountHelp()}`;$('logout').onclick=e=>signout(e.target);return}
 if((mode==='forgot-password'||mode==='reset-password')&&config.chatgpt&&session.user?.provider!=='email'){title('Account recovery');root.innerHTML='<h1>Your sign-in is managed by ChatGPT.</h1><p>Use ChatGPT’s account recovery when you need to restore access. DigitalBurj never stores your ChatGPT password.</p><a class="btn primary" href="/sign-in">Return to secure sign-in</a>'+accountHelp();return}
 if(mode==='reset-password'){if(!session.signedIn){root.innerHTML='<h1>Use your recovery link.</h1><p>Open the link from your recovery email or sign in before changing your password.</p><a class="btn primary" href="/forgot-password">Request a recovery email</a>';return}form('Choose a new password','Sign in again after updating your password.',(session.user?.purpose==='recovery'?'':input('currentPassword','Current password',{type:'password',extra:'autocomplete="current-password"'}))+newPassword(),'Update password');$('account-form').onsubmit=e=>submit(e,async data=>{const result=await api('auth/password','POST',{password:data.get('password'),currentPassword:data.get('currentPassword')});message(result.message);ready=false;root.insertAdjacentHTML('beforeend','<p><a class="btn primary" href="/sign-in">Sign in with your new password</a></p>')});return}
 if(config.chatgpt)nativeEntry();else standardForm();window.ToolIcons.decorate(root);
}
boot().catch(error=>{message(error.message,'error');if(!$('account-form'))root.innerHTML='<h1>Let’s get you back in.</h1><p>Use secure sign-in to continue. Courses and tools remain locked.</p><a class="btn primary" href="/sign-in">Sign in</a>'});
})();
